import * as z from "zod";

export const schema = z
  .object({
    people: z
      .array(
        z
          .object({
            id: z.string().min(1, "ID is required.").meta({
              title: "ID",
              description:
                "A hidden stable identifier generated by the setup page.",
            }),
            slugs: z
              .array(
                z
                  .object({
                    isActive: z.boolean().default(true).meta({
                      title: "Is Active",
                      description:
                        "Whether this slug is active and should be used to access the person.",
                    }),
                    slug: z.string().min(1, "Slug is required.").meta({
                      title: "Slug",
                      description:
                        "A unique URL slug generated from the person's name.",
                    }),
                  })
                  .meta({
                    title: "Slug",
                    description:
                      "A unique URL slug generated from the person's name.",
                  }),
              )
              .default([])
              .meta({
                title: "Slugs",
                description:
                  "The list of slugs including historical ones that can be used to access the person.",
              }),
            name: z.string().min(1, "Name is required.").meta({
              title: "Name",
              description: "The full name of the person.",
            }),
          })
          .meta({
            title: "Person",
            description:
              "Metadata for a person. Additional details like contact info and schedules are stored in a separate file named after their ID.",
          }),
      )
      .default([])
      .meta({
        title: "People",
        description:
          "The list of people associated with organisations, such as teachers, staff, or committee members.",
      }),
  })
  .meta({
    title: "People Configuration",
    description:
      "Configuration for people metadata supporting organisation detail pages.",
  });

export const buildSchema = schema.extend({}).partial();

export type TInput = z.input<typeof schema>;
export type TOutput = z.output<typeof schema>;
export type TModel = TOutput;

export const defaultValues: TInput = {
  people: [],
};
